commit;

-- 5) Check
select status, count(*) as listings,
       (select count(*) from public.property_images i join public.properties p2 on p2.id = i.property_id
         where p2.source = 'brighton' and p2.status = p.status) as photos
from public.properties p where source = 'brighton' group by status;
